fn shift_letters(s: Str, n: Int) -> Str {
    let mut result = ""
    for c in chars(s) {
        let shifted = match c {
            'a'..='z' => {
                let base = ord('a')
                let offset = (ord(c) - base + n) % 26
                chr(base + offset)
            },
            _ => c,
        }
        result = concat(result, str(shifted))
    }
    result
}

